const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
function write(rel, name, value){
  const out = path.join(root, rel);
  fs.writeFileSync(out, `/* generated by scripts/bundle_runtime.js */\nwindow.${name}=${JSON.stringify(value)};\n`);
}

function csvCell(v){
  const s = Array.isArray(v) ? v.join(' | ') : (v ?? '').toString();
  return /[",\n]/.test(s) ? '"'+s.replace(/"/g,'""')+'"' : s;
}
function writeCsv(rel, headers, rows){
  const out=path.join(root,rel);
  const text=[headers.join(','),...rows.map(r=>headers.map(h=>csvCell(r[h])).join(','))].join('\n')+'\n';
  fs.writeFileSync(out,text,'utf8');
}

global.window = {DOT_DATA:require('./assemble_data')()};
write('data/data_bundle.js','DOT_DATA',window.DOT_DATA);

const catalogHeaders=['string','round','status','type','entity','group','geography','themes','contention_count','strange','city','placeholder','provenance','sources','current_root_status','current_as_of','formal_type','editorial_designation','origin_round','historical_rounds','registry_entity','registry_country','technical_contact_organization','technical_contact_country','represented_place','application_entity','registration_date','contention_year','origin_round_sources','ascii_string','record_level','root_listed'];
writeCsv('data/explorer_catalog.csv', catalogHeaders, (window.DOT_DATA.explorer||[]).map(r=>({
  string:r.string,round:r.round,status:r.status,type:r.type,entity:r.entity,group:r.group,geography:r.geography,themes:r.themes||[],contention_count:r.contentionCount??'',strange:r.strange?'yes':'no',city:r.city?'yes':'no',placeholder:r.placeholder?'yes':'no',provenance:r.provenanceKey?(r.provenanceKey+(r.provenanceDate?' · '+r.provenanceDate:'')):'',sources:r.source||[],current_root_status:r.currentRootStatus,current_as_of:r.currentAsOf,formal_type:r.formalType,editorial_designation:r.editorialDesignation,origin_round:r.originRound,historical_rounds:r.historicalRounds,registry_entity:r.registryEntity,registry_country:r.registryCountry,technical_contact_organization:r.technicalContactOrganization,technical_contact_country:r.technicalContactCountry,represented_place:r.representedPlace,application_entity:r.applicationEntity,registration_date:r.registrationDate,contention_year:r.contentionYear,origin_round_sources:r.originRoundSources||[],ascii_string:r.asciiString,record_level:r.recordLevel,root_listed:r.rootListed?'yes':'no'
})));
